@fragment
fn fs_ripple(in: VertexOut) -> @location(0) vec4<f32> {
    return tap(in.uv) * (0.5 + 0.5 * sin(frame.time));
}

override taps: i32 = 4;

@fragment
fn fs_ripple(in: VertexOut) -> @location(0) vec4<f32> {
    return tap(in.uv) * f32(taps) * 0.25;
}

@vertex
fn vs_ripple(@builtin(vertex_index) i: u32) -> VertexOut {
    let p = vec2<f32>(f32(i % 2u), f32(i / 2u));
    return VertexOut(vec4<f32>(p * 2.0 - 1.0, 0.0, 1.0), p);
}

@fragment
fn fs_ripple(in: VertexOut) -> @location(0) vec4<f32> {
    return tap(in.uv);
}

@fragment
fn fs_ripple(in: VertexOut) -> @location(0) vec4<f32> {
    return tap(in.uv) + grid_position(in.uv) * 0.0;
}

