fn particle(p: Sprite) -> Sprite {
    var o = p;
    o.size = p.size * 2.0;
    return o;
}

files.transitions/wipe.wgsl:
fn transition(c: Crossing) -> Crossing {
    var o = c;
    o.color = mix(before(c.uv), after(c.uv), step(c.uv.x, c.progress));
    return o;
}
